<?php
namespace App\Http\Controllers\Staff;
use App\Http\Controllers\Controller; use App\Models\StaffAgreement; use App\Models\StaffMember; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str; use Illuminate\View\View;
class StaffPortalController extends Controller {
 public function showLogin(): View{return view('staff.login');}
 public function login(Request $request): RedirectResponse { $c=$request->validate(['email'=>['required','email'],'password'=>['required','string']]); if(!Auth::guard('staff')->attempt($c,$request->boolean('remember')))return back()->withErrors(['email'=>'Invalid staff login details.'])->onlyInput('email'); $request->session()->regenerate(); $staff=Auth::guard('staff')->user(); if(!$staff instanceof StaffMember||$staff->employment_status==='TERMINATED'){Auth::guard('staff')->logout();return redirect()->route('staff.login')->with('error','This staff portal account is unavailable.');} return $staff->employment_agreement_accepted_at?redirect()->route('staff.dashboard'):redirect()->route('staff.agreement.show'); }
 public function dashboard(): View { $staff=$this->staff(); return view('staff.dashboard',['staff'=>$staff,'leaveRequests'=>$staff->leaveRequests()->latest()->get(),'salaryPayments'=>$staff->salaryPayments()->latest('period')->get(),'kycDocuments'=>$staff->kycDocuments()->latest()->get(),'payoutRequests'=>$staff->payoutChangeRequests()->latest()->get()]); }
 public function agreement(): View { $staff=$this->staff(); $agreement=$staff->agreements()->where('agreement_type','EMPLOYMENT')->latest('id')->firstOrCreate(['agreement_type'=>'EMPLOYMENT','version'=>'v1'],['content'=>'TradeX employment agreement. By accepting, you confirm that you have read and agree to the employment terms, confidentiality obligations and workplace policies.']); return view('staff.agreement',compact('staff','agreement')); }
 public function acceptAgreement(Request $request): RedirectResponse { $staff=$this->staff(); $request->validate(['accept'=>['accepted']]); $agreement=$staff->agreements()->where('agreement_type','EMPLOYMENT')->latest('id')->firstOrFail(); $agreement->update(['accepted_at'=>now(),'accepted_ip'=>$request->ip(),'accepted_user_agent'=>Str::limit((string)$request->userAgent(),2000)]); $staff->forceFill(['employment_agreement_accepted_at'=>now(),'employment_agreement_version'=>$agreement->version])->save(); return redirect()->route('staff.dashboard')->with('success','Employment agreement accepted.'); }
 public function terminationAgreement(): View { $staff=$this->staff(); abort_unless($staff->employment_status==='TERMINATION_PENDING',404); $agreement=$staff->agreements()->where('agreement_type','TERMINATION')->latest('id')->firstOrFail(); return view('staff.termination-agreement',compact('staff','agreement')); }
 public function acceptTerminationAgreement(Request $request): RedirectResponse { $staff=$this->staff(); abort_unless($staff->employment_status==='TERMINATION_PENDING',422); $request->validate(['accept'=>['accepted']]); $agreement=$staff->agreements()->where('agreement_type','TERMINATION')->latest('id')->firstOrFail(); $agreement->update(['accepted_at'=>now(),'accepted_ip'=>$request->ip(),'accepted_user_agent'=>Str::limit((string)$request->userAgent(),2000)]); $staff->update(['termination_agreement_accepted_at'=>now(),'termination_agreement_version'=>$agreement->version,'employment_status'=>'TERMINATED']); Auth::guard('staff')->logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); return redirect()->route('staff.login')->with('success','Termination agreement acknowledgement recorded.'); }
 public function storeKyc(Request $request): RedirectResponse { $staff=$this->staff(); $data=$request->validate(['document_type'=>['required','in:ID_FRONT,ID_BACK,ADDRESS_PROOF'],'document'=>['required','file','mimes:jpg,jpeg,png,pdf','max:10240']]); $file=$request->file('document'); $path='staff/kyc/'.$staff->uuid.'/'.$data['document_type'].'-'.Str::uuid().'.'.$file->extension(); Storage::disk('private')->put($path,file_get_contents($file->getRealPath()),['visibility'=>'private']); $staff->kycDocuments()->updateOrCreate(['document_type'=>$data['document_type']],['storage_disk'=>'private','document_path'=>$path,'status'=>'PENDING','review_note'=>null,'reviewed_by_admin_id'=>null,'reviewed_at'=>null]); return back()->with('success','KYC document submitted for Super Admin review.'); }
 public function savePayoutDetails(Request $request): RedirectResponse { $staff=$this->staff(); $data=$request->validate(['bank_account_holder'=>['required','string','max:150'],'bank_name'=>['required','string','max:150'],'bank_branch'=>['nullable','string','max:150'],'bank_account_number'=>['required','string','max:120'],'usdt_network'=>['required','string','max:32'],'usdt_address'=>['required','string','max:255'],'reason'=>['nullable','string','max:1000']]); if($staff->payout_details_locked_at){$staff->payoutChangeRequests()->create(['requested_details'=>$data,'reason'=>$data['reason']??'Staff requested payout detail change.','status'=>'PENDING']);return back()->with('success','Payout detail change sent to Super Admin for approval.');} $staff->forceFill(['bank_account_holder'=>$data['bank_account_holder'],'bank_name'=>$data['bank_name'],'bank_branch'=>$data['bank_branch']??null,'bank_account_number_encrypted'=>$data['bank_account_number'],'usdt_network'=>$data['usdt_network'],'usdt_address_encrypted'=>$data['usdt_address'],'payout_details_locked_at'=>now()])->save();return back()->with('success','Payout details saved and locked. Future changes require Super Admin approval.'); }
 public function storeLeave(Request $request): RedirectResponse {$staff=$this->staff();$data=$request->validate(['starts_on'=>['required','date','after_or_equal:today'],'ends_on'=>['required','date','after_or_equal:starts_on'],'leave_type'=>['required','string','max:40'],'reason'=>['required','string','max:2000']]);$staff->leaveRequests()->create($data+['status'=>'PENDING']);return back()->with('success','Leave request sent for approval.');}
 public function logout(Request $request): RedirectResponse {Auth::guard('staff')->logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('staff.login');}
 private function staff(): StaffMember {$staff=Auth::guard('staff')->user();abort_unless($staff instanceof StaffMember && $staff->employment_status!=='TERMINATED',401);return $staff;}
}
